amb(z) as (values (1290),(1410),(1534),(1565),(1595),(1608),(1738),(1787),(2345),(2748),(2827),(3206),(3801),(4564),(5017),(6010),(6340),(6356),(6388),(6452),(7315),(8212),(8495),(8525),(8546),(8640),(8866),(8872),(9105),(9442)),
cible as (
  select l.id, r.ct as attendu
  from market_listings l
  join reg r on l.postal_code ~ '^[0-9]{4}$' and l.postal_code::int between r.lo and r.hi
  where l.source_portal = 'realadvisor'
    and l.transaction_type = 'buy'
    and l.status = 'removed'
    and r.ct <> 'FL'
    and l.postal_code::int not in (select z from amb)
    and l.canton is distinct from r.ct
)
update market_listings m set canton = c.attendu
from cible c where m.id = c.id;
